use split_decls_genesis :: ourprelude :: * ; #[doc = " Helper trait that allows `arena_cache` queries to return `Option<&T>`"] #[doc = " instead of `&Option<T>`, and avoid allocating `None` in the arena."] #[doc = ""] #[doc = " An arena-cached query must be declared to return a type that implements"] #[doc = " this trait, i.e. either `&'tcx T` or `Option<&'tcx T>`. This trait then"] #[doc = " determines the types returned by the provider and stored in the arena,"] #[doc = " and provides a function to bridge between the three types."] pub trait ArenaCached < 'tcx > : Sized { #[doc = " Type that is returned by the query provider."] type Provided ; #[doc = " Type that is stored in the arena."] type Allocated : 'tcx ; #[doc = " Takes a provided value, and allocates it in the arena (if appropriate)"] #[doc = " with the help of the given `arena_alloc` closure."] fn alloc_in_arena (arena_alloc : impl Fn (Self :: Allocated) -> & 'tcx Self :: Allocated , value : Self :: Provided ,) -> Self ; } impl < 'tcx , T > ArenaCached < 'tcx > for & 'tcx T { type Provided = T ; type Allocated = T ; fn alloc_in_arena (arena_alloc : impl Fn (Self :: Allocated) -> & 'tcx Self :: Allocated , value : Self :: Provided ,) -> Self { arena_alloc (value) } } impl < 'tcx , T > ArenaCached < 'tcx > for Option < & 'tcx T > { type Provided = Option < T > ; #[doc = " The provide value is `Option<T>`, but we only store `T` in the arena."] type Allocated = T ; fn alloc_in_arena (arena_alloc : impl Fn (Self :: Allocated) -> & 'tcx Self :: Allocated , value : Self :: Provided ,) -> Self { value . map (arena_alloc) } }